slots.VIEW:
SIM = {
  duration: 2,
  stage: {"u0":0,"u1":10,"v0":0,"v1":6},
  bodies: [
    { id: "e0", at: function (s) { const b = s.e0; return [b.cx ?? b.x, b.cy ?? b.y]; } }
  ],
  phases: [{ t0: 0, t1: 0.5 }, { t0: 0.5, t1: 1 }, { t0: 1, t1: 2 }],
};

slots.drawFrame:
const cx = state.e0.cx;
const pistonW = state.e0.w;
const halfW = pistonW / 2 + 0.08;

const yC = 0.8;      // 缸底 c
const yB = 2.8;      // 卡销 b
const yA = 3.0;      // 卡销 a
const yTop = 4.3;    // 缸口

// 地面（与缸底齐平，汽缸落地不悬空）
Draw.ground(0, 10, yC);

// 封闭气体：从缸底到活塞下表面
Draw.polygon([
  [cx - halfW, yC],
  [cx + halfW, yC],
  [cx + halfW, state.e0.cy],
  [cx - halfW, state.e0.cy]
], { hatch: "below" });

// 静止汽缸：左右缸壁 + 缸底
Draw.line([cx - halfW, yC], [cx - halfW, yTop], { width: 4 });
Draw.line([cx + halfW, yC], [cx + halfW, yTop], { width: 4 });
Draw.line([cx - halfW, yC], [cx + halfW, yC], { width: 4 });

// 卡销 a（上）与卡销 b（下），从两侧缸壁向内伸出
Draw.line([cx - halfW, yA], [cx - halfW + 0.18, yA], { width: 5 });
Draw.line([cx + halfW - 0.18, yA], [cx + halfW, yA], { width: 5 });
Draw.line([cx - halfW, yB], [cx - halfW + 0.18, yB], { width: 5 });
Draw.line([cx + halfW - 0.18, yB], [cx + halfW, yB], { width: 5 });

// 轻质活塞（水平薄板，位置由 state 给出）
Draw.box([cx, state.e0.cy], pistonW, state.e0.h);

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(2, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "piston.x", label: "piston 水平位置", value: state.e0.x, unit: 'm' });
out.push({ key: "piston.y", label: "piston 竖直位置", value: state.e0.y, unit: 'm' });
out.push({ key: "piston.vx", label: "piston 水平速度", value: (b.e0.x - a.e0.x) / dt, unit: 'm/s' });
out.push({ key: "piston.vy", label: "piston 竖直速度", value: (b.e0.y - a.e0.y) / dt, unit: 'm/s' });
return out;
